class Solution {
  public int minOperations(int[] nums, int[] target) {
    boolean[] seen = new boolean[100_001];
    int count = 0;
    for (int i = 0; i < nums.length; i++) {
      if (nums[i] != target[i] && !seen[nums[i]]) {
        seen[nums[i]] = true;
        count++;
      }
    }
    return count;
  }
}
